// === Tab: mySketch ===
const moverAmount = 1200; //how many particles are added at the beginning of the sketch
const pAndMSize = 5; //the side length of each particle (they're rects).

let pointsAndMovers = []; //container for both moving and fixed particles

let bgCol;


function setup() {
	createCanvas(360, 360);
	background(bgCol=color(0));

	noStroke();
	for (let i = 0; i < moverAmount; i++) {
		pointsAndMovers.push(new pointMover(rInc(width, pAndMSize), rInc(height, pAndMSize), false));
	}
	for (let i = 2; i > 0; i--){
	let fixedStart = random(pointsAndMovers);
	//fixedStart.pos.set(inc(width/2, pAndMSize), inc(height/2, pAndMSize));
	fixedStart.fixed = true;                   //choose one of the particles at random from the container and make it "fixed".
	}
	frameRate(60);
}

function draw() {
	background(bgCol);
	for (let point of pointsAndMovers) {
			if (point.fixed===false){
		point.move();                        //only call the particle's move() method if it's not fixed
			} else if (point.fixed===true){
		point.show();  
			}//draw the particle.
	}

}

class pointMover {
	constructor(x, y, fixed = true, shade=rCol(), size = pAndMSize) {
		this.pos = createVector(x, y);
		this.fixed = fixed;
		this.shade=shade;
		this.size = size;
	}

	show() {
			fill(this.shade);
			rect(this.pos.x, this.pos.y, this.size , this.size);
	}

	move() {
			let direction = random([1, 0])
			if (direction === 1) {
				this.pos.x += randOne(this.size);
			} else if (direction === 0) {
					this.pos.y += randOne(this.size);
			}
			pgWrap(this.pos, [0, inc(width, this.size), 0, inc(height, this.size)]); //using a wrap function from my personal function library to wrap moving particles' positions.
			for (let otherPoint of pointsAndMovers) {
				if (otherPoint !== this && otherPoint.fixed === true && abs(dist(this.pos.x, this.pos.y, otherPoint.pos.x, otherPoint.pos.y)) <= this.size) {
					this.fixed = true;
					if(this.pos.x<=this.size){
						this.pos.x=width-this.size;
					} else if (this.pos.y <=this.size){
						this.pos.y = height-this.size;
					} else if (this.pos.x >= width-this.size){
						this.pos.x = this.size;
					} else if (this.pos.y >= height-this.size){
						this.pos.y = this.size;
					} else {
						this.pos = this.pos;
					}

						//the above section ensures that newly fixed particles which whould otherwise wrap to the other side actually fix in a position as if they had been wrapped.

					this.shade=rLerpColor(lerpColor(this.shade, otherPoint.shade, 0.9)) //make any newly fixed particle shift its shade to something much closer to that of the particle that caused it to "fix", creating a gradient effect.
				}
			}
		}
}

